window.kbPageData["views/entry/k-47d878f249ba0f93"] = {"key":"entry/k-47d878f249ba0f93","state":{"route":"entry/k-47d878f249ba0f93"},"node":{"id":"k-47d878f249ba0f93","mode":"k","title":"多边形内角和","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["多边形内角和公式"],"qs":["国考 2024 地市级 行测#70","国考 2024 行政执法 行测#69"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"directorySummary":"在平面上，边界不自相交的 n 边形（n≥3）的内角和为（n−2）×180°。","review":{"title":"多边形内角和","type":"原理与机制","definition":"在平面上，边界不自相交的 n 边形（n≥3）的内角和为（n−2）×180°。","explanation":"沿多边形内部互不相交的对角线，可将它分成 n−2 个三角形。各三角形的内角合起来恰好组成原多边形的各内角。该公式也适用于凹多边形，凹顶点按大于 180° 的内部角计入。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"国考 2024 地市级 行测#70":"用五边形内角和辨认道路图中缺少的转角条件，再结合已知路长比较周长区间。","国考 2024 行政执法 行测#69":"用五边形内角和辨认道路图中缺少的转角条件，再结合已知路长比较周长区间。"}},"aspects":[{"title":"由五边形内角和求未知转角","uses":[{"unit":"Q1","role":"解题依据","use":"小区道路围成五边形，页图标明 ∠A、∠C、∠E 均为 90°，∠B 为 135°。从 540° 中减去这四个内角，得 ∠D 为 135°。据此作等腰直角三角形，结合三段已知路长求得周长约为 214.1 米，选 B。","evidence":"因五边形内角和为","qids":["国考 2024 地市级 行测#70"]},{"unit":"Q2","role":"解题依据","use":"同一小区道路周长题，页图中的四个已知内角与 Q1 一致。由五边形内角和确定 D 处转角，为计算缺失路段长度提供角度条件，答案同为 B。","evidence":"根据多边形内角和公式","qids":["国考 2024 行政执法 行测#69"]}]}]},"questions":{"国考 2024 地市级 行测#70":{"paper":"国考 2024 地市级 行测","n":70,"mod":"数量关系","src":["92d0b72e86a6a33d568d.pdf",12],"asrc":["e1792c53900a45f1b9fa.pdf",21],"card":"3254bdd04bb896a20759d1a0","links":[{"id":"k-47d878f249ba0f93","role":"解题依据","why":"用五边形内角和减去四个已知内角，可求出剩余转角。"}]},"国考 2024 行政执法 行测#69":{"paper":"国考 2024 行政执法 行测","n":69,"mod":"数量关系","src":["dfddc59dc6e7d9da5d71.pdf",12],"asrc":["6493f3a6a55c38431852.pdf",21],"card":"c8340eb2a10cbcfa2e1f166b","links":[{"id":"k-47d878f249ba0f93","role":"解题依据","why":"由五边形内角和及四个已知内角求出剩余的转角。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-47d878f249ba0f93":[["国考 2024 地市级 行测#70"],["国考 2024 行政执法 行测#69"]]}};
